cases.setup_script:
set -e
fixture=/opt/bashos-parity/payload-image-tiny
[ -f /bash-os/bl-pkg.sh ] && [ -r /bash-os/bl-pkg.sh ] || { echo 'CONTROL-FAILED image helper unavailable' >&2; exit 98; }
[ -f "$fixture/repo/INDEX" ] && [ -f "$fixture/SHA256SUMS" ] || { echo 'CONTROL-FAILED image-owned fixture unavailable' >&2; exit 98; }
(cd "$fixture" && /usr/bin/sha256sum -c SHA256SUMS) >/dev/null || { echo 'CONTROL-FAILED fixture digest' >&2; exit 98; }
/usr/bin/cp -a "$fixture/repo" repo
mkdir -p root/usr/share/payload-image-tiny root/var/lib/bl-pkg/installed root/usr/share/unrelated
printf 'keep\n' > root/usr/share/unrelated/keep
printf 'payload image fixture\n' > "$HOME/payload-expected"

